<!DOCTYPE html><html lang="id"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"><title><?= htmlspecialchars($title) ?> — Ujian ASTS</title><link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap" rel="stylesheet"><style>*{box-sizing:border-box}body{margin:0;min-height:100vh;background:#f5f7fb;font-family:Inter,Arial,sans-serif;display:grid;place-items:center;padding:20px;color:#111827}.box{width:min(430px,100%);background:#fff;border:1px solid #e5e7eb;border-radius:22px;padding:34px;box-shadow:0 24px 60px #0f172a12}.back{font-size:11px;color:#6b7280;text-decoration:none}.tag{display:inline-block;margin-top:30px;background:<?= $role === 'admin' ? '#111827' : '#eef2ff' ?>;color:<?= $role === 'admin' ? '#fff' : '#4f46e5' ?>;border-radius:8px;padding:7px 10px;font-size:10px;font-weight:800}.box h1{font-size:26px;margin:15px 0 7px}.sub{font-size:12px;color:#6b7280;line-height:1.6;margin-bottom:25px}.alert{display:none;padding:11px;border-radius:9px;background:#fef2f2;color:#b91c1c;font-size:11px;margin-bottom:15px}.alert.show{display:block}.field{margin-bottom:15px}.field label{display:block;font-size:11px;font-weight:800;margin-bottom:7px}.field input{width:100%;height:44px;border:1px solid #d1d5db;border-radius:10px;padding:0 12px;outline:0;font-size:12px}.field input:focus{border-color:#818cf8;box-shadow:0 0 0 4px #6366f11a}.btn{width:100%;height:44px;border:0;border-radius:10px;background:<?= $role === 'admin' ? '#111827' : '#4f46e5' ?>;color:#fff;font-weight:800;cursor:pointer}.links{text-align:center;margin-top:20px;font-size:11px}.links a{color:#4f46e5;font-weight:800;text-decoration:none}.note{text-align:center;color:#9ca3af;font-size:10px;margin-top:14px}</style></head><body><main class="box"><a class="back" href="login.php">← Pilih jenis login</a><div class="tag"><?= $role === 'admin' ? 'ADMIN ACCESS' : 'USER ACCESS' ?></div><h1><?= htmlspecialchars($title) ?></h1><div class="sub"><?= htmlspecialchars($subtitle) ?></div><div id="alert" class="alert"></div><form id="form"><div class="field"><label>Email</label><input type="email" name="email" autocomplete="email" required placeholder="nama@email.com"></div><div class="field"><label>Password</label><input type="password" name="password" autocomplete="current-password" required placeholder="Masukkan password"></div><button id="btn" class="btn" type="submit">Login</button></form><div class="links"><?php if($role==='user'): ?>Belum punya akun? <a href="register.php">Register</a><?php else: ?>Bukan admin? <a href="login_user.php">Login User</a><?php endif; ?></div><div class="note">Login dilindungi session dan password hash.</div></main><script>const form=document.getElementById('form'),box=document.getElementById('alert'),btn=document.getElementById('btn');form.addEventListener('submit',async e=>{e.preventDefault();btn.disabled=true;btn.textContent='Memproses...';box.className='alert';try{const r=await fetch('<?= $action ?>',{method:'POST',body:new FormData(form)});const d=await r.json();if(!d.success)throw new Error(d.message||'Login gagal');box.textContent=d.message;box.style.background='#ecfdf5';box.style.color='#047857';box.className='alert show';setTimeout(()=>location.href=d.redirect,500)}catch(err){box.textContent=err.message;box.style.background='#fef2f2';box.style.color='#b91c1c';box.className='alert show'}finally{btn.disabled=false;btn.textContent='Login'}});</script></body></html>
